#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200005;
const int MAXM = MAXN * 20;  // 主席树节点数: N * logN

// 主席树节点
struct Node {
    int lc, rc;   // 左孩子、右孩子下标
    int sum;      // 区间内元素个数
} tree[MAXM];

int root[MAXN];   // root[i] 表示前缀 A[1..i] 对应的线段树根节点
int tot;          // 节点计数器
vector<long long> values;  // 离散化数组

// 建空树
int build(int l, int r) {
    int now = ++tot;
    if (l == r) {
        tree[now].sum = 0;
        return now;
    }
    int mid = (l + r) >> 1;
    tree[now].lc = build(l, mid);
    tree[now].rc = build(mid + 1, r);
    tree[now].sum = 0;
    return now;
}

// 更新：在 pre 的基础上，位置 pos 的计数 +1
int update(int pre, int l, int r, int pos) {
    int now = ++tot;
    tree[now] = tree[pre];      // 复制前一个版本
    tree[now].sum++;            // 计数 +1
    if (l == r) return now;
    int mid = (l + r) >> 1;
    if (pos <= mid)
        tree[now].lc = update(tree[pre].lc, l, mid, pos);
    else
        tree[now].rc = update(tree[pre].rc, mid + 1, r, pos);
    return now;
}

// 查询区间 [L, R] 的第 k 小
int query(int u, int v, int l, int r, int k) {
    if (l == r) return l;  // 返回离散化下标
    int leftSum = tree[tree[v].lc].sum - tree[tree[u].lc].sum;  // 左子树元素个数
    int mid = (l + r) >> 1;
    if (k <= leftSum)
        return query(tree[u].lc, tree[v].lc, l, mid, k);
    else
        return query(tree[u].rc, tree[v].rc, mid + 1, r, k - leftSum);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<long long> A(N + 1);
    for (int i = 1; i <= N; ++i) {
        cin >> A[i];
        values.push_back(A[i]);
    }

    // 离散化
    sort(values.begin(), values.end());
    values.erase(unique(values.begin(), values.end()), values.end());

    // 建空树
    root[0] = build(0, (int)values.size() - 1);

    // 逐点插入，建立可持久化线段树
    for (int i = 1; i <= N; ++i) {
        int pos = lower_bound(values.begin(), values.end(), A[i]) - values.begin();
        root[i] = update(root[i - 1], 0, (int)values.size() - 1, pos);
    }

    // 处理询问
    while (Q--) {
        int L, R, K;
        cin >> L >> R >> K;
        int pos = query(root[L - 1], root[R], 0, (int)values.size() - 1, K);
        cout << values[pos] << '\n';
    }

    return 0;
}

