#include <bits/stdc++.h>
using namespace std;

int N;
int HP = 100, STA = 100, HUNGER = 0, MP = 50, GOLD = 0;
int pos = 0;
string actions;

// 随机数生成（固定种子以保证可复现）
mt19937 rng(123456);

void processEvent(int e) {
    if (e == 1) { // Monster
        if (STA >= 20) STA -= 20;
        else {
            HP -= 20;
            STA = 0;
        }
    } else if (e == 2) { // Treasure
        int gold = rng() % 41 + 10; // 10~50
        GOLD += gold;
    } else if (e == 3) { // Fountain
        MP = min(100, MP + 20);
        HP = min(100, HP + 10);
    } else if (e == 4) { // Trap
        HP -= 15;
    } else if (e == 5) { // Camp
        HP = min(100, HP + 10);
        HUNGER = max(0, HUNGER - 10);
    }
}

void takeAction(char act, int w) {
    if (w == 3) { // 暴风雪：无法移动，只能休息
        act = 'S';
    }
    if (act == 'L') {
        if (STA >= 5) {
            pos--;
            if (w == 2) STA -= 10; // 雨天加倍
            else STA -= 5;
        } else {
            // 体力不足，无法移动，强制休息
            act = 'S';
        }
    } else if (act == 'R') {
        if (STA >= 5) {
            pos++;
            if (w == 2) STA -= 10;
            else STA -= 5;
        } else {
            act = 'S';
        }
    }
    if (act == 'S') {
        HP = min(100, HP + 5);
        HUNGER += 5;
    }
    // 魔法迷雾：随机方向移动（如果选择移动）
    if (w == 4 && (act == 'L' || act == 'R')) {
        // 随机左右
        if (rng() % 2 == 0) pos--; else pos++;
    }
}

void endDay(int w, int day) {
    // 饥饿增加
    HUNGER += (w == 3 ? 15 : 10);
    // 天气影响HP
    if (w == 2) HP -= 1;
    else if (w == 3) HP -= 3;
    // 检查死亡
    if (HP <= 0 || HUNGER > 100) {
        cout << "Game Over at day " << day << endl;
        exit(0);
    }
}

int main() {
    cin >> N;
    vector<int> weather(N), event(N);
    for (int i = 0; i < N; ++i) cin >> weather[i] >> event[i];
    cin >> actions;

    for (int day = 1; day <= N; ++day) {
        processEvent(event[day-1]);
        char act = actions[day-1];
        takeAction(act, weather[day-1]);
        endDay(weather[day-1], day);
    }
    // 存活
    cout << "Survived!\n";
    cout << "HP: " << HP << "\n";
    cout << "STA: " << STA << "\n";
    cout << "HUNGER: " << HUNGER << "\n";
    cout << "MP: " << MP << "\n";
    cout << "GOLD: " << GOLD << "\n";
    return 0;
}

